import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data.split()[0])

    for i in range(n):
        if i == 0 or i == n - 1 or n <= 2:
            print('*' * n)
        else:
            print('*' + ' ' * (n - 2) + '*')

if __name__ == '__main__':
    main()
